export function createIsExternal (viteServer: ViteDevServer, nuxt: Nuxt) {
  const inlinePatterns = [
    /virtual:/,
    /\.ts$/,
    ...(viteServer.config.ssr.noExternal || [])
  ]
  const externalPatterns = [
    /node_modules/,
    new RegExp('^' + escapeStringRegexp(withTrailingSlash(resolve(nuxt.options.rootDir, nuxt.options.dir.shared)))),
    ...(viteServer.config.ssr.external || [])
  ]
  return (id: string) => {
    if (inlinePatterns.some(pattern => pattern.test(id))) {
      return { external: false }
    }
    if (externalPatterns.some(pattern => pattern.test(id))) {
      return { external: true, id }
    }
    return { external: false }
  }
}
